import itertools
import json

def solve_puzzle():
    # Puzzle parameters
    houses = [1, 2]  # left to right
    names = ["Eric", "Arnold"]
    styles = ["victorian", "colonial"]
    smoothies = ["cherry", "desert"]
    pets = ["dog", "cat"]

    # Helper to find index of value in assignment list
    def idx(lst, val):
        return lst.index(val)

    # Try all assignments (permutations preserve uniqueness per house)
    for name_perm in itertools.permutations(names):
        for style_perm in itertools.permutations(styles):
            # Clue 3: Victorian is somewhere to the left of Eric
            if not (idx(style_perm, "victorian") < idx(name_perm, "Eric")):
                continue

            for smoothie_perm in itertools.permutations(smoothies):
                for pet_perm in itertools.permutations(pets):
                    # Clue 1: Cherry smoothie owner is the dog owner
                    if idx(smoothie_perm, "cherry") != idx(pet_perm, "dog"):
                        continue

                    # Clue 2: Victorian house resident is the dog owner
                    if idx(style_perm, "victorian") != idx(pet_perm, "dog"):
                        continue

                    # Found a consistent solution
                    rows = []
                    for i, house in enumerate(houses):
                        rows.append([
                            str(house),
                            name_perm[i],
                            style_perm[i],
                            smoothie_perm[i],
                            pet_perm[i],
                        ])
                    header = ["House", "Name", "style of house", "favorite smoothie", "type of pet"]
                    return {"solution": {"header": header, "rows": rows}}

    # If no solution found (should not happen for a well-posed puzzle)
    return {"solution": {"header": ["House", "Name", "style of house", "favorite smoothie", "type of pet"], "rows": []}}

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
